-- V5: 动态正文补充 + 新增动态
--
-- 背景：V2 种子的 feed_post 没写 content 列，App 动态详情页点进去正文全空。
-- 纯数据迁移，无 DDL，sqlite / mysql 两边通用。

-- 1. 给现有 10 条种子动态补正文（按标题定位，与 V2 的 INSERT 顺序一致）
UPDATE feed_post SET content = '两天一夜反穿武功山，全程 13.5 公里，累计爬升 1200 米。第一天下午从龙山村上山，四点到发云界草甸扎营，运气好赶上日落金顶。夜里风大到帐篷呼呼作响，凌晨四点半摸黑冲金顶，五点四十云海破晓，那一下觉得什么都值了。注意山顶夜里零度上下，冲锋衣羽绒都要带，水源在发云界补给点最后确认一次。' WHERE title = '武功山反穿：两天一夜看云海日出全记录';
UPDATE feed_post SET content = '带五岁的娃走莫干山蒋公道，全程 11 公里缓坡，石板路好走，树荫遮阳，十分适合亲子。途中剑池瀑布孩子看呆了，走两步歇三步也不着急，四个半小时慢慢晃下来。山脚民宿的笋干烧肉是本日最佳。提醒：推车不友好，建议背架或牵手慢行，防蚊液必带。' WHERE title = '莫干山小环线，亲子徒步初体验';
UPDATE feed_post SET content = '雨崩第三天，从上村出发去神瀑往返 10 公里。前半段林间缓坡很舒服，最后两公里开始下冰雹，翻出雨衣硬着头皮走。到了神瀑底下风大得站不稳，但经幡在风里猎猎作响的画面这辈子忘不掉。高反不明显但坡陡喘，节奏放慢多喝水。回程在神瀑客栈喝了酥油茶，圆满。' WHERE title = '雨崩村徒步第三天，神瀑下面的风太大了';
UPDATE feed_post SET content = '香山人太多，这次换了一条冷门线：从憋死猫小道上山，挂甲塔方向下，全程 9 公里，爬升 600 米。红叶已经到了峰值边缘，越往高处越红，下午四点的侧逆光里整面山坡像烧起来。沿途基本没人，只碰到两拨遛狗的大爷。公交 346 回城，完美避开人潮。' WHERE title = '香山红叶快到峰值了，周末冲了一条冷门线';
UPDATE feed_post SET content = '虎跳峡高路，两天徒步全程 22 公里。第一天中途客栈著名的 28 拐，爬到怀疑人生，但拐完看见玉龙雪山正面横在江对岸，值回票价。夜里住 half way 的观景台，星空好到不像话。第二天下到中虎跳江边，涛声震耳。路况整体不错，雨季注意塌方段，登山杖强烈建议。' WHERE title = '虎跳峡高路徒步：一条值得走第二遍的线';
UPDATE feed_post SET content = '第一次重装，徽杭古道 18 公里，背了 12 公斤。出发前紧张了三天，实际走下来发现最难的不是腿，是背包肩带磨锁骨——记得提前贴好肌贴。蓝天凹扎营看星星，江南第一关的石阶比想象中陡。给新手的建议：水带两升、负重先从体重的六分之一起步，别学我头铁。' WHERE title = '新手第一次重装，徽杭古道 18km 打卡';
UPDATE feed_post SET content = '梧桐山夜爬，晚八点从梧桐山村出发，凌四点登顶好汉坡。全程 9.5 公里，头灯照着只能看见前面三米的台阶，全靠同伴的播客撑着走。五点五十日出破云，整个深圳从暗蓝色里一点点亮起来，那一刻凌晨的疲惫清零。下山腿软，但下周还想再来。夜爬必带头灯备用电池。' WHERE title = '梧桐山夜爬看日出，凌晨四点的深圳';
UPDATE feed_post SET content = '赶上帐篷节，观音宕人从众，帐篷一顶挨一顶像下饺子。但晚上十点云海翻上草甸的时候，所有人同时安静了。人在这样的时刻确实会掉鸡皮疙瘩。人多也有多玩法：草甸音乐节、夜市摊子、凌晨排队看日出的陌生人都很可爱。避峰建议：错开节假日，选普通周末。' WHERE title = '武功山帐篷节人从众，但云海值了';
UPDATE feed_post SET content = '凌晨两点出发，六小时登顶四姑娘山大峰，5025 米，人生第一座五千米。全程其实是走出来的雪山，技术难度低，但高反不跟你讲道理——最后一百米每走十步喘三十秒。登顶那一刻眼泪差点下来。建议提前一周喝红景天，到大本营当晚早睡，冲顶节奏小步高频。' WHERE title = '四姑娘山大峰登顶，人生第一座 5000+';
UPDATE feed_post SET content = '三天两晚，武功山到明月山穿越，全程约 35 公里，是反穿线的加长plus版。D1 龙山村到发云界，D2 发云界经羊狮幕到明月山，D3 缆车下山泡温泉。第二天的连续草甸脊线是全程精华，风大景美。补给点比想象中多，但旺季住宿要提前订。重装党闭眼冲的路线。' WHERE title = '武功山—明月山穿越，三天两晚行程贴';

-- 2. 新增动态（coverUrl 留空走渐变占位，status=1 上线）
INSERT INTO feed_post (title, author, like_count, city, cover_url, cover_aspect_ratio, status, content) VALUES
('天目山七尖纵走，华东虐线入门第一课', '浙西山鼠', 152, '杭州', NULL, 1.20, 1,
 '七尖纵走，一天连翻七座千米山头，全程 25 公里，爬升 2000 米，华东入门虐线名副其实。第五尖桐杭岗之后基本是看不见尽头的防火道，晒到怀疑人生。山上无补水点，四升水起步。走完膝盖废了三天，但朋友圈装到了，血赚。建议春秋两季去，夏天真会中暑。'),
('麦理浩径第二段：海与山的完美一天', '维港过客', 189, '香港', NULL, 1.05, 1,
 '麦理浩径二段，西湾亭到北潭凹，12 公里。一边是西湾和咸田湾的白沙滩，一边是蚺蛇尖的尖顶，海和山同时塞进取景框。中途在咸田湾下水游泳半小时，这才是徒步该有的样子。士多奶茶补给很及时。口岸过关加船程，一天来回完全来得及。'),
('恩施大峡谷一炷香，膝盖和眼睛都在受难', '清江漫步', 97, '恩施', NULL, 1.35, 1,
 '恩施大峡谷七星寨线，全程 8.5 公里台阶路，下峡谷再上绝壁，小腿抖成筛子。一炷香那根 150 米高的石柱孤零零立在群山里，照片拍不出十分之一的震撼。云龙地缝的瀑布群是意外之喜。台阶多到崩溃，护膝和登山杖不是可选项，是必需品。'),
('东北第一峰白云峰冬夏两爬对比记录', '长白来客', 233, '白山', NULL, 0.90, 1,
 '同一座山冬夏各爬了一次。夏天：绿苔石阶、云雾、凉得刺骨的矿泉水。冬天：零下二十六度，睫毛结冰，风大时根本站不稳，但雾凇和雪山连成一片的白色世界一辈子见不了几回。结论：夏天看绿，冬天看白，各值得一次。冬季必须冰爪加羽绒服加热贴全套。');
